<script setup lang="ts">
import { ref, reactive, computed } from 'vue'
import { useI18n } from 'vue-i18n'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Plus, EditPen, Delete, Connection } from '@element-plus/icons-vue'
import { p3, type ExternalConnection } from '@/mocks/phase3'
import { MESSAGE_BOX_CONFIRM_DEFAULTS } from '@/constants/messageBox'
type Connector=NonNullable<ExternalConnection['connector']>
type Authentication=NonNullable<ExternalConnection['authentication']>
const {t}=useI18n(),visible=ref(false),editing=ref(''),draft=reactive({name:'',url:'',connector:'salesforce' as Connector,authentication:'client-credentials' as Authentication,clientId:'',secret:'',tokenUrl:'',apiKeyHeader:'X-API-Key'})
const testing=ref(''),testingDraft=ref(false),testedDraft=ref(''),draftResult=ref('')
let request=0
const original=computed(()=>p3.connections.find(c=>c.id===editing.value))
const authOptions=computed(()=>['client-credentials'] as Authentication[])
const authLabel=(mode:Authentication)=>t('phase3.auth_'+mode)
const connectorOf=(row:ExternalConnection):Connector=>row.connector||(row.id==='sfdc'?'salesforce':'http-api')
const authOf=(row:ExternalConnection):Authentication=>row.authentication||(row.useClientCredentials||row.clientId||connectorOf(row)==='salesforce'?'client-credentials':'none')
const fingerprint=()=>JSON.stringify([draft.url.trim(),draft.connector,draft.authentication,draft.authentication==='client-credentials'?draft.clientId.trim():'',draft.authentication==='client-credentials'&&draft.connector==='http-api'?draft.tokenUrl.trim():'',draft.authentication==='api-key'?draft.apiKeyHeader.trim():'',draft.authentication==='none'?'':draft.secret])
const valid=computed(()=>{
 if(!draft.name.trim()||!/^https:\/\/\S+$/i.test(draft.url.trim())||!authOptions.value.includes(draft.authentication))return false
 if(draft.authentication==='none')return true
 if(!draft.secret.trim())return false
 if(draft.authentication==='client-credentials')return !!draft.clientId.trim()&&(draft.connector==='salesforce'||/^https:\/\/\S+$/i.test(draft.tokenUrl.trim()))
 return draft.authentication!=='api-key'||/^[A-Za-z0-9_-]+$/.test(draft.apiKeyHeader.trim())
})
const canSave=computed(()=>valid.value&&!testingDraft.value&&testedDraft.value===fingerprint()&&draftResult.value==='success')
function changeConnector(){draft.authentication=draft.connector==='salesforce'?'client-credentials':'none';changeAuth()}
function changeAuth(){draft.secret=draft.authentication==='none'?'':'demo-secret-not-real';testedDraft.value='';draftResult.value=''}
function open(row?:ExternalConnection){request++;testingDraft.value=false;editing.value=row?.id||'';Object.assign(draft,{name:row?.name||'',url:row?.url||'',connector:'salesforce',authentication:'client-credentials',clientId:row?.clientId||'',secret:'demo-secret-not-real',tokenUrl:row?.tokenUrl||'',apiKeyHeader:row?.apiKeyHeader||'X-API-Key'});testedDraft.value='';draftResult.value='';visible.value=true}
function close(){request++;draft.secret='';testedDraft.value='';draftResult.value='';testingDraft.value=false}
async function testDraft(){if(!valid.value||testingDraft.value)return;const version=++request,key=fingerprint();testingDraft.value=true;draftResult.value='';await new Promise(r=>setTimeout(r,1000));if(version!==request||!visible.value)return;testingDraft.value=false;if(key!==fingerprint())return;draftResult.value=draft.url.includes('/fail')||(draft.authentication!=='none'&&draft.secret==='fail')?'failed':'success';testedDraft.value=key;ElMessage[draftResult.value==='success'?'success':'error'](t(draftResult.value==='success'?'phase3.mockConnectionSuccess':'phase3.connectionFailed'))}
function save(){if(!canSave.value){ElMessage.warning(t('phase3.testBeforeSave'));return}const old=original.value,now=new Date().toLocaleString('ja-JP'),row:ExternalConnection={id:old?.id||crypto.randomUUID(),name:draft.name.trim(),url:draft.url.trim(),connector:draft.connector,authentication:draft.authentication,clientId:draft.authentication==='client-credentials'?draft.clientId.trim():undefined,tokenUrl:draft.authentication==='client-credentials'&&draft.connector==='http-api'?draft.tokenUrl.trim():undefined,apiKeyHeader:draft.authentication==='api-key'?draft.apiKeyHeader.trim():undefined,useClientCredentials:draft.authentication==='client-credentials',secretConfigured:draft.authentication!=='none',created:old?.created||now,creator:old?.creator||'管理者',updated:now,updatedBy:'管理者',testStatus:'success',testedUrl:draft.url.trim()};if(old)Object.assign(old,row);else p3.connections.push(row);draft.secret='';visible.value=false;ElMessage.success(t('phase3.saved'))}
async function test(row:ExternalConnection){if(testing.value)return;const auth=authOf(row);if(auth!=='none'&&(!row.secretConfigured||(auth==='client-credentials'&&!row.clientId))){open(row);return}testing.value=row.id;const snapshot=JSON.stringify([row.url,connectorOf(row),auth,row.clientId,row.tokenUrl,row.apiKeyHeader]);await new Promise(r=>setTimeout(r,1000));if(snapshot===JSON.stringify([row.url,connectorOf(row),authOf(row),row.clientId,row.tokenUrl,row.apiKeyHeader])){row.testStatus=/^https:\/\/\S+$/i.test(row.url)&&!row.url.includes('/fail')?'success':'failed';row.testedUrl=row.url;ElMessage[row.testStatus==='success'?'success':'error'](t(row.testStatus==='success'?'phase3.mockConnectionSuccess':'phase3.connectionFailed'))}testing.value=''}
async function remove(row:ExternalConnection){if(Object.values(p3.masters).some(c=>c.connection===row.id)){ElMessage.warning(t('phase3.inUse'));return}try{await ElMessageBox.confirm(t('phase3.deleteConfirm'),row.name,MESSAGE_BOX_CONFIRM_DEFAULTS);p3.connections=p3.connections.filter(c=>c.id!==row.id)}catch{}}
</script>
<template><div class="p3-connections"><div class="p3-end"><el-button type="primary" :icon="Plus" @click="open()">{{t('phase3.addConnection')}}</el-button></div><el-table :data="p3.connections" border><el-table-column type="index" label="No." width="64"/><el-table-column prop="name" :label="t('phase3.name')" min-width="160"/><el-table-column prop="url" :label="t('phase3.url')" min-width="240" show-overflow-tooltip/><el-table-column prop="created" :label="t('phase3.created')" min-width="180"/><el-table-column :label="t('phase3.status')" width="100"><template #default="{row}"><el-tag :type="row.testStatus==='success'&&row.testedUrl===row.url?'success':'info'">{{t(row.testStatus==='success'&&row.testedUrl===row.url?'phase3.connectionValid':'phase3.connectionInvalid')}}</el-tag></template></el-table-column><el-table-column prop="creator" :label="t('phase3.creator')" width="120"/><el-table-column :label="t('phase3.connectionAudit')" min-width="180"><template #default="{row}">{{row.updated||'—'}}<span v-if="row.updatedBy"> / {{row.updatedBy}}</span></template></el-table-column><el-table-column :label="t('phase3.actions')" width="280"><template #default="{row}"><el-button link type="primary" :icon="Connection" :loading="testing===row.id" :disabled="!!testing&&testing!==row.id" @click="test(row)">{{t('phase3.connectionTest')}}</el-button><el-button link type="primary" :icon="EditPen" @click="open(row)">{{t('phase3.edit')}}</el-button><el-button link type="danger" :icon="Delete" @click="remove(row)">{{t('phase3.delete')}}</el-button></template></el-table-column></el-table>
<el-dialog v-model="visible" :title="t('phase3.connection')" width="600px" destroy-on-close @closed="close"><el-form label-position="top"><el-form-item :label="t('phase3.name')" required><el-input v-model="draft.name"/></el-form-item>
<div class="p3-auth-choice"><el-form-item :label="t('phase3.connector')" required><el-select v-model="draft.connector" @change="changeConnector"><el-option value="salesforce" label="Salesforce"/></el-select></el-form-item><el-form-item :label="t('phase3.authentication')" required><el-select v-model="draft.authentication" @change="changeAuth"><el-option v-for="mode in authOptions" :key="mode" :value="mode" :label="authLabel(mode)"/></el-select></el-form-item></div>
<el-form-item :label="t('phase3.url')" required><el-input v-model="draft.url" :placeholder="draft.connector==='salesforce'?'https://example.my.salesforce.com':'https://api.example.com'"/></el-form-item>
<template v-if="draft.authentication==='client-credentials'"><el-form-item v-if="draft.connector==='http-api'" :label="t('phase3.tokenUrl')" required><el-input v-model="draft.tokenUrl" placeholder="https://api.example.com/oauth/token"/></el-form-item><el-form-item :label="t('phase3.clientId')" required><el-input v-model="draft.clientId" autocomplete="off"/></el-form-item><el-form-item :label="t('phase3.clientSecret')" required><el-input v-model="draft.secret" type="password" show-password autocomplete="new-password"/></el-form-item></template>
<template v-else-if="draft.authentication==='api-key'"><el-form-item :label="t('phase3.apiKeyHeader')" required><el-input v-model="draft.apiKeyHeader"/></el-form-item><el-form-item :label="t('phase3.apiKeyValue')" required><el-input v-model="draft.secret" type="password" show-password autocomplete="new-password"/></el-form-item></template>
<el-form-item v-else-if="draft.authentication==='bearer-token'" :label="t('phase3.bearerToken')" required><el-input v-model="draft.secret" type="password" show-password autocomplete="new-password"/></el-form-item>
</el-form><template #footer><el-button @click="visible=false">{{t('phase3.cancel')}}</el-button><el-button :icon="Connection" :loading="testingDraft" :disabled="!valid" @click="testDraft">{{t('phase3.connectionTest')}}</el-button><el-button type="primary" :disabled="!canSave" @click="save">{{t('phase3.save')}}</el-button></template></el-dialog></div></template>
<style scoped>.p3-auth-choice{display:grid;grid-template-columns:1fr 1fr;gap:16px}.p3-auth-choice .el-select{width:100%}.p3-end{display:flex;justify-content:flex-end;margin:8px 0 16px}.p3-secret{display:flex;gap:12px;width:100%;align-items:center}.p3-demo-note,.p3-impact{font-size:13px;color:var(--el-text-color-secondary);line-height:1.7;margin-top:12px}.p3-impact{background:var(--el-fill-color-light);padding:10px 12px;border-radius:4px}</style>
